#include "game.hpp"
#include "json.hpp"
#include "mode_handoff.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace hyperion;
namespace {
int checks=0;void check(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}bool near(double a,double b){return std::abs(a-b)<1e-6;}
nlohmann::json snapshot(const State& s){auto path=std::filesystem::temp_directory_path()/"hyperion-continuity-test.json";std::string e;check(saveState(s,path.string(),e),"Snapshot saves");std::ifstream in(path);nlohmann::json j;in>>j;in.close();std::filesystem::remove(path);return j;}
void deploy(Game& g){g.system("HOME");g.s.selectedPlanet=2;check(g.descend(),"Deploy fixture");g.s.surface=g.s.waypoint={3200,1800};g.parkFlight(2,g.s.surface);g.s.economy.missions.clear();g.s.economy.contracts.clear();g.s.economy.routes.clear();g.s.flight.traffic.clear();for(auto& site:g.s.economy.settlements)site.owner=1;}
}
int main(){try{
 for(const char* seed:{"MERIDIAN-0001","GLASS-002","DEEP-BLUE"}){
  Game g(seed);g.ensureEconomy();g.system("HOME");g.s.selectedPlanet=1;auto chosen=g.universe.minorBodies("HOME").front().id;g.selectedMinor=chosen;auto before=snapshot(g.s);g.enterFlight();auto helm=g.s.flight.ship;double hour=g.s.hours;for(int i=0;i<200;i++){g.transferPlan("strategy");g.transferPlan("cockpit");}g.openStrategy();check(g.s.mode==Mode::System&&g.s.selectedPlanet==1&&g.selectedMinor==chosen,"System return retains body and minor selection");check(g.s.hours==hour&&near(g.s.flight.ship.throttle,helm.throttle)&&hyperion::flight::length(g.s.flight.ship.position-helm.position)<1e-8,"Chart return preserves physical ship and spends no time");
  g.galaxy();g.s.galaxy={512,122};g.s.galaxyZoom=1.8;g.s.selectedStar="HOME";g.enterFlight();g.s.galaxy={0,0};g.s.galaxyZoom=.4;g.issueOrder("strategy");check(g.s.mode==Mode::Galaxy&&g.s.galaxy.x==512&&g.s.galaxy.y==122&&g.s.galaxyZoom==1.8,"Galaxy camera and selection survive cockpit edits");auto frozen=snapshot(g.s);g.openStrategy();check(snapshot(g.s)==frozen,"Repeated strategy entry is idempotent");g.enterFlight();g.chartRecall.star="OTHER-SYSTEM";g.openStrategy();check(g.s.mode==Mode::System&&g.s.viewStar==g.s.currentStar,"Stale remembered system cannot steal the current chart");
  Game surface(seed);deploy(surface);surface.s.waypoint={3310,1840};surface.focusedContact="remembered-surface-contact";hour=surface.s.hours;check(surface.transferPlan("cockpit").available&&surface.transferPlan("cockpit").hours==0,"Surface boarding is quoted as free");surface.enterFlight();check(surface.s.hours==hour&&surface.s.flight.docked,"Boarding retains a physically landed ship");check(surface.disembark(),"Redeploy same site");check(distance(surface.s.waypoint,{3310,1840})<1e-6&&surface.focusedContact=="remembered-surface-contact","Surface destination and focus restored at the actual landing site");check(near(surface.s.hours,hour+1),"Redeployment costs exactly one turn");
  surface.enterFlight();surface.parkFlight(2,{3900,2400});surface.s.flight.deployed=false;check(surface.disembark(),"Deploy elsewhere");check(distance(surface.s.waypoint,surface.s.surface)<1e-6&&!surface.surveyRecall.valid,"Landing elsewhere cannot inherit a remote expedition route");
  Game ocean(seed);deploy(ocean);check(ocean.dive(),"Dive fixture");ocean.s.oceanTargetX=ocean.s.oceanX+90;ocean.s.targetDepth=std::min(ocean.maxDepth(),ocean.s.depth+240);double x=ocean.s.oceanTargetX,depth=ocean.s.targetDepth;auto quote=ocean.transferPlan("cockpit");check(quote.hours==1&&quote.text.find("remembered")!=std::string::npos,"Submersible recovery clearly quotes its turn and recall");hour=ocean.s.hours;ocean.enterFlight();check(near(ocean.s.hours,hour+1)&&ocean.s.mode==Mode::Flight,"Recovering submersible resolves its actual turn");check(ocean.disembark()&&ocean.surveyRecall.dive,"Same-site redeployment retains the pending dive route");check(ocean.dive(),"Resume dive");check(near(ocean.s.oceanTargetX,x)&&near(ocean.s.targetDepth,depth)&&ocean.s.depth<depth&&!ocean.surveyRecall.valid,"Dive restores the target while physically starting from the surface");
  ocean.s.oceanTargetX+=40;ocean.s.targetDepth=std::min(ocean.maxDepth(),ocean.s.depth+180);x=ocean.s.oceanTargetX;depth=ocean.s.targetDepth;ocean.surface();check(ocean.dive()&&near(ocean.s.oceanTargetX,x)&&near(ocean.s.targetDepth,depth),"Manual surface and re-dive also preserve the planned target");
  ocean.s.oceanTargetX+=30;x=ocean.s.oceanTargetX;ocean.surface();ocean.enterFlight();check(ocean.disembark()&&ocean.surveyRecall.dive,"Surface then boarding preserves a still-pending dive route");check(ocean.dive()&&near(ocean.s.oceanTargetX,x),"Pending dive target survives the extra cockpit transition");
  frozen=snapshot(ocean.s);for(int i=0;i<100;i++)for(const char* a:{"cockpit","strategy","deploy","dive","surface","launch"})ocean.transferPlan(a);check(snapshot(ocean.s)==frozen,"Transfer previews cannot mutate the campaign");
  ocean.reset("NEXT");check(!ocean.chartRecall.valid&&!ocean.surveyRecall.valid&&ocean.transferNotice.empty(),"New campaign cannot inherit old plans");
 }
 Game charge;deploy(charge);charge.s.battery=1;auto frozen=snapshot(charge.s);auto q=charge.fieldQuote("fieldRecharge");check(q.available&&q.move.turns==3&&snapshot(charge.s)==frozen,"Recharge quotes exact recovery time without advancing it");double hour=charge.s.hours;charge.issueOrder("fieldRecharge");check(near(charge.s.hours,hour+3)&&near(charge.s.battery,13)&&charge.lastTurn.hours==3,"Recharge resolves only required full hours and one report");frozen=snapshot(charge.s);charge.issueOrder("fieldRecharge");check(snapshot(charge.s)==frozen,"Ready scanner cannot spend unnecessary hours recharging");
 charge.s.battery=0;Contract c;c.id="RECHARGE-DEADLINE";c.settlement=charge.s.economy.settlements.front().id;c.accepted=true;c.deadline=charge.s.hours+2.5;charge.s.economy.contracts.push_back(c);hour=charge.s.hours;charge.issueOrder("fieldRecharge");check(near(charge.s.hours,hour+2)&&charge.s.battery==8&&charge.toast.find("deadline")!=std::string::npos,"Recharge returns control before the accepted deadline");frozen=snapshot(charge.s);charge.issueOrder("fieldRecharge");check(snapshot(charge.s)==frozen,"Imminent deadline blocks another automatic recharge");
 Game approach;deploy(approach);auto planet=approach.activePlanet();Contact contact;bool found=false;for(int cx=30;cx<40&&!found;cx++)for(int cy=20;cy<30&&!found;cy++)for(const auto& c:approach.universe.surfaceObjects(planet,cx,cy))if(c.kind=="mineral"){contact=c;found=true;break;}check(found,"Find generated approach target");approach.s.surface={contact.pos.x-85,contact.pos.y};approach.s.waypoint=approach.s.surface;approach.registerExpeditionHabitat();for(int x=int(approach.s.surface.x/86)-8;x<=int(approach.s.surface.x/86)+8;x++)for(int y=int(approach.s.surface.y/86)-8;y<=int(approach.s.surface.y/86)+8;y++)for(const auto& c:approach.universe.surfaceObjects(planet,x,y))if(c.kind=="signal"||c.kind=="relic")approach.s.scanned.insert(c.id);
 frozen=snapshot(approach.s);q=approach.fieldQuote("fieldApproach",contact.id);check(q.available&&snapshot(approach.s)==frozen,"Approach preview is free and read-only");hour=approach.s.hours;approach.issueOrder("fieldApproach",contact.id);check(near(approach.s.hours,hour+3)&&distance(approach.s.surface,contact.pos)<=34&&distance(approach.s.surface,contact.pos)>1,"Approach stops in survey range without requiring arrival at its centre");check(approach.fieldQuote("fieldStudy",contact.id).available&&approach.lastTurn.events.front().find("Study range reached")!=std::string::npos,"Approach hands control back to the study choice");frozen=snapshot(approach.s);approach.issueOrder("fieldApproach",contact.id);check(snapshot(approach.s)==frozen,"Already reachable contact does not spend another approach turn");
 approach.s.battery=0;frozen=snapshot(approach.s);approach.issueOrder("fieldRecharge","",true);check(snapshot(approach.s)==frozen,"Pause blocks convenience orders");approach.s.depth=approach.maxDepth()+20;approach.s.mode=Mode::Ocean;frozen=snapshot(approach.s);approach.issueOrder("fieldRecharge");check(snapshot(approach.s)==frozen,"Recharge refuses unplanned unsafe pressure exposure");
 std::cout<<"PASS: "<<checks<<" continuity checks / remembered charts, exact physical handoffs, same-site plans, ocean targets, pure previews, survey approach, recharge, deadlines and pause\n";return 0;
}catch(const std::exception& e){std::cerr<<"Continuity failure after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
